<?php
declare(strict_types=1);
require_once __DIR__.'/lib/auth.php';
$user=require_login();
$config=require __DIR__.'/config/config.php';
$expired=!user_can_use_workspace($user);
$expiryTimestamp=!empty($user['expires_at'])?strtotime((string)$user['expires_at']):false;
$expiryLabel=$expiryTimestamp?date('d/m/Y H:i',$expiryTimestamp):'Chưa xác định';

// Dynamic asset version: changes with server datetime on every page render,
// so browser reloads receive a fresh JS/CSS URL instead of a fixed cache key.
$assetVersion=date('YmdHis');

// Remaining subscription time: calculate from the current server time,
// not from the original payment duration. Do not use ceil(seconds / 86400),
// because that can show "30 days" when only 29 calendar days remain.
$remainingDays=0;
if($expiryTimestamp && $expiryTimestamp>time()){
    $now=new DateTimeImmutable('now');
    $expiryDate=(new DateTimeImmutable())->setTimestamp($expiryTimestamp);
    $remainingDays=(int)$now->diff($expiryDate)->days;
}

$subscription=null;
try {
    $stmt=db()->prepare("SELECT plan_code,plan_name,days,amount,paid_at,expires_at FROM payment_orders WHERE user_id=? AND status='paid' ORDER BY paid_at DESC,id DESC LIMIT 1");
    $stmt->execute([(int)$user['id']]);
    $subscription=$stmt->fetch() ?: null;
} catch (Throwable $e) {
    $subscription=null;
}
$planName=$subscription['plan_name']??'Chưa có gói';
$planCode=$subscription['plan_code']??'';
?>
